// Temporary input/camera owner; the room keeps the actual cabinet and prize state.
import{stickVector}from'../input.js';
export const CLAW_BODY=`<header class="claw-heading"><strong>작은 인형뽑기</strong><button data-claw-exit aria-label="인형뽑기 나가기">나가기 ×</button></header><div class="claw-court" data-claw-court tabindex="0" role="img" aria-label="도름이 앞의 실제 집게와 세 인형"></div><section class="claw-panel" aria-label="집게 조작"><p data-claw-status role="status" aria-live="polite"></p><div class="claw-controls"><div class="dpad stick-controls claw-stick-controls"><button class="movement-stick" data-claw-stick type="button" aria-label="집게 이동 스틱. 밀어서 움직여요" aria-describedby="claw-stick-help"><span class="stick-track" aria-hidden="true"></span><span class="stick-knob claw-stick-knob" data-claw-stick-knob aria-hidden="true">✦</span></button><span id="claw-stick-help">스틱을 밀어 집게를 움직여요</span></div><div class="claw-directions"><button type="button" data-claw-up aria-label="집게를 안쪽으로">↑</button><button type="button" data-claw-left aria-label="집게를 왼쪽으로">←</button><button type="button" data-claw-right aria-label="집게를 오른쪽으로">→</button><button type="button" data-claw-down aria-label="집게를 앞쪽으로">↓</button></div><div class="claw-actions"><button type="button" data-claw-grab>집게 내리기</button><button type="button" data-claw-repeat hidden>한 번 더</button><button type="button" data-claw-pause>잠깐 쉬기</button></div></div><small>스틱 또는 방향키로 움직여요 · Space 잡기 · Esc 나가기</small></section>`;
const directions={left:[-1,0],right:[1,0],up:[0,-1],down:[0,1]},codes={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'};
export function createClawController({stage,getView,getRoom,getActors,isAllowed=()=>true,onActive=()=>{},clearInput=()=>{},ui={toast(){}},createCamera,doc=globalThis.document,win=globalThis.window}){
 let live=null,disposed=false;
 const current=s=>!!s&&live===s&&getView()===s.source&&getRoom()==='amusementIsland';
 const listen=(s,node,type,fn,options)=>{node?.addEventListener(type,fn,options);s.listeners.push([node,type,fn,options]);};
 function resetStick(s){const id=s.stickPointer;s.stickPointer=null;s.stick={x:0,z:0};const node=s.stickNode,knob=s.stickKnob;if(knob)knob.style.transform='translate(0px, 0px)';node?.classList.remove('is-pressed');if(id!==null){try{if(node?.hasPointerCapture?.(id))node.releasePointerCapture(id);}catch{}}}
 function clear(s){s.keys.clear();s.pointers.clear();resetStick(s);s.machine.model.setInput(0,0);clearInput();}
 function close(s=live){if(!s||live!==s)return;live=null;clear(s);s.machine.model.pause();for(const[n,t,f,o]of s.listeners)n?.removeEventListener(t,f,o);try{s.view.dispose?.();}finally{s.root.remove();stage.classList.remove('claw-open');doc.body?.classList.remove('claw-open');onActive(false);if(!doc.hidden)doc.querySelector?.('#scene')?.focus?.({preventScroll:true});}}
 function render(s){if(!current(s))return;const a=s.machine.model.snapshot(),$=q=>s.root.querySelector(q),aim=a.phase==='aim'&&!a.paused;
  const text=a.paused?'잠깐 멈췄어요. 계속하기로 이어 갈 수 있어요':a.phase==='aim'?'인형 위에 집게를 맞춘 뒤 내려 보세요':a.phase==='result'?(a.result==='caught'?'인형이 앞쪽 받침에 도착했어요!':'조금 빗나갔어요. 다시 맞춰 볼까요?'):a.phase.startsWith('return')?'같은 인형을 원래 자리에 돌려놓고 있어요':({lower:'집게가 천천히 내려가요',close:'집게를 오므려요',lift:'인형을 들어 올려요',carry:'앞쪽 받침으로 옮겨요',release:'집게를 열어요',drop:'인형이 받침에 내려와요'}[a.phase]??'집게가 움직이고 있어요');
  if(text!==s.status){$('[data-claw-status]').textContent=text;s.status=text;}
  for(const direction of Object.keys(directions))$('[data-claw-'+direction+']').disabled=!aim;$('[data-claw-stick]').disabled=!aim;
  $('[data-claw-grab]').disabled=!aim;$('[data-claw-grab]').hidden=a.phase==='result';$('[data-claw-repeat]').hidden=a.phase!=='result';$('[data-claw-repeat]').disabled=a.paused;
  $('[data-claw-pause]').textContent=a.paused?'계속하기':'잠깐 쉬기';s.root.dataset.phase=a.phase;s.machine.apply(a);
 }
 function fail(s){close(s);ui.toast?.('집게를 멈췄어요. 잠깐 뒤 다시 열어 주세요');}
 function pause(s=live){if(!current(s))return;clear(s);s.machine.model.pause();render(s);}
 function input(s){if(!current(s))return;let x=s.stick.x,z=s.stick.z;for(const name of[...s.keys.values(),...s.pointers.values()]){x+=directions[name][0];z+=directions[name][1];}s.machine.model.setInput(x,z);}
 function moveStick(s,e){if(!current(s)||e.pointerId!==s.stickPointer)return;e.preventDefault();const r=s.stickNode.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,radius=Math.min(r.width,r.height)*.34,v=stickVector(dx,-dy,radius),n=Math.max(1,Math.hypot(dx,dy)/radius);s.stick=v;s.stickKnob.style.transform=`translate(${dx/n}px, ${dy/n}px)`;input(s);}
 function act(s,kind){if(!current(s)||doc.hidden)return;clear(s);try{if(kind==='pause'){if(s.machine.model.snapshot().paused)s.machine.model.resume();else s.machine.model.pause();}else if(kind==='grab')s.machine.model.grab();else s.machine.model.repeat();render(s);}catch{fail(s);}}
 function open(){if(disposed||live||doc.hidden||getRoom()!=='amusementIsland'||!isAllowed())return false;const source=getView(),machine=source?.clawMachine,actors=getActors();if(!machine||!machine.canReach(actors?.player?.position))return false;const root=doc.createElement('div');root.className='claw-overlay';root.innerHTML=CLAW_BODY;root.setAttribute('role','group');root.setAttribute('aria-label','작은 인형뽑기');stage.appendChild(root);let s,view;
   try{view=createCamera({machine,...actors,source});const $=q=>root.querySelector(q);s={root,view,machine,source,listeners:[],keys:new Map(),pointers:new Map(),stickPointer:null,stick:{x:0,z:0},stickNode:$('[data-claw-stick]'),stickKnob:$('[data-claw-stick-knob]'),fit:null,status:''};live=s;stage.classList.add('claw-open');doc.body?.classList.add('claw-open');clear(s);onActive(true);
   listen(s,$('[data-claw-exit]'),'click',()=>close(s));for(const kind of['grab','repeat','pause'])listen(s,$('[data-claw-'+kind+']'),'click',()=>act(s,kind));
   const stick=s.stickNode;listen(s,stick,'pointerdown',e=>{if(!current(s)||stick.disabled||s.stickPointer!==null||e.button!==0||e.isPrimary===false)return;e.preventDefault();s.stickPointer=e.pointerId;stick.setPointerCapture?.(e.pointerId);stick.classList.add('is-pressed');moveStick(s,e);});listen(s,stick,'pointermove',e=>moveStick(s,e));listen(s,stick,'pointerup',e=>{if(!current(s)||e.pointerId!==s.stickPointer)return;resetStick(s);input(s);});for(const type of['pointercancel','lostpointercapture'])listen(s,stick,type,e=>{if(current(s)&&e.pointerId===s.stickPointer)pause(s);});
   for(const direction of Object.keys(directions)){const node=$('[data-claw-'+direction+']');listen(s,node,'pointerdown',e=>{if(!current(s)||node.disabled||e.button!==0||e.isPrimary===false)return;e.preventDefault();s.pointers.set(e.pointerId,direction);node.setPointerCapture?.(e.pointerId);input(s);});for(const type of['pointerup','pointercancel','lostpointercapture'])listen(s,node,type,e=>{if(!current(s)||!s.pointers.has(e.pointerId))return;s.pointers.delete(e.pointerId);if(type!=='pointerup')pause(s);else input(s);});listen(s,node,'click',e=>{if(!current(s)||node.disabled||e.detail!==0||s.pointers.size||s.keys.size)return;clear(s);const[x,z]=directions[direction];machine.model.setInput(x,z);machine.model.update(1/12);machine.model.setInput(0,0);render(s);});}
   listen(s,doc,'keydown',e=>{if(!current(s)||e.ctrlKey||e.metaKey||e.altKey)return;if(e.code==='Escape'){e.preventDefault();e.stopImmediatePropagation?.();if(!e.repeat)close(s);return;}const stickFocused=e.target?.matches?.('[data-claw-stick]')===true;if(e.target?.tagName==='BUTTON'&&!stickFocused){if(e.repeat&&['Enter','Space'].includes(e.code)){e.preventDefault();e.stopImmediatePropagation?.();}return;}if(['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))return;if(!codes[e.code]&&!['Space','Enter'].includes(e.code))return;e.preventDefault();e.stopImmediatePropagation?.();if(e.repeat)return;if(codes[e.code]){s.keys.set(e.code,codes[e.code]);input(s);}else if(!machine.model.snapshot().paused)act(s,'grab');},{capture:true});
   listen(s,doc,'keyup',e=>{if(!current(s)||!s.keys.has(e.code))return;e.preventDefault();e.stopImmediatePropagation?.();s.keys.delete(e.code);input(s);},{capture:true});
   listen(s,win,'blur',()=>pause(s));listen(s,doc,'visibilitychange',()=>{if(doc.hidden)pause(s);});listen(s,win,'pagehide',()=>close(s));listen(s,win,'resize',()=>{if(current(s)){clear(s);s.fit=null;}});render(s);$('[data-claw-court]').focus?.({preventScroll:true});return true;
  }catch{if(live===s&&s)close(s);else{view?.dispose?.();root.remove();}ui.toast?.('인형뽑기를 준비하지 못했어요. 다시 열어 주세요');return false;}
 }
 function viewport(width,height){const s=live;if(!s)return{x:0,y:0,width,height};try{const b=s.root.querySelector('[data-claw-court]').getBoundingClientRect(),base=stage.getBoundingClientRect(),x=Math.max(0,b.left-base.left),y=Math.max(0,b.top-base.top),r={x,y,width:Math.max(1,Math.min(b.width,width-x)),height:Math.max(1,Math.min(b.height,height-y))},key=JSON.stringify(r);if(key!==s.fit){s.view.fit(r.width,r.height);s.fit=key;}return r;}catch{fail(s);return{x:0,y:0,width,height};}}
 return{open,close:()=>close(),cancel:()=>close(),dispose:()=>{disposed=true;close();},pause,get active(){return !!live;},get camera(){return live?.view.camera;},viewport,snapshot:()=>live?.machine.model.snapshot()??null,tick(dt,{paused=false}={}){const s=live;if(!s)return;if(!current(s)){close(s);return;}if(doc.hidden||paused){pause(s);return;}try{s.machine.model.update(dt);render(s);}catch{fail(s);}}};
}
